// 100 motoristas de exemplo, de pontos e bairros variados (endereços reais do IBGE), em vários horários e dias. dias: 0 = domingo a 6 = sábado.
// Cada lugar é o nome de um ponto de lugares.js ou [nome, lat, lng]. tipo: carro (padrão) ou moto (1 vaga).
const at = (title) => PLACES.find((p) => p.title === title).point;
const lugar = (x) => (typeof x === 'string' ? { nome: x, point: at(x) } : { nome: x[0], point: [x[1], x[2]] });
const WEEK = [1, 2, 3, 4, 5];
const driver = (n, nome, origem, destino, hora, dias, vagas_livres, tipo = 'carro') => {
  const o = lugar(origem);
  const d = lugar(destino);
  return { id: `exd-${n}`, motorista: nome, origem: o.nome, destino: d.nome, from: o.point, to: d.point, hora, dias, vagas_livres, tipo, isExample: true };
};
